<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class QualityController extends Controller{
private function ok(Request $r,$manage=false){$u=$r->user();$x=$u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head')||$u->hasRole('quality_head')||$u->canDo($manage?'quality.manage':'quality.view');abort_unless($x,403);}
private function auto($pid){$g=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where('l.academic_period_id',$pid)->whereIn('gr.value',['2','3','4','5']);$avg=round((float)$g->avg(DB::raw('CAST(gr.value AS REAL)')),2);$a=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('l.academic_period_id',$pid);$at=(clone $a)->count();$present=(clone $a)->whereIn('a.status',['present','late'])->count();$debts=DB::table('semester_results')->where('academic_period_id',$pid)->whereIn(DB::raw('LOWER(value)'),['2','незачет','незачёт','не зачтено'])->count();$plans=DB::table('curriculum_plans')->where('academic_period_id',$pid);$pc=(clone $plans)->count();$approved=(clone $plans)->where('approval_status','approved')->count();$pr=DB::table('practice_placements')->where('academic_period_id',$pid);$pt=(clone $pr)->count();$done=(clone $pr)->where('status','completed')->count();return ['avg_grade'=>$avg,'attendance'=>$at?round($present*100/$at,1):0,'academic_debts'=>$debts,'approved_programs'=>$pc?round($approved*100/$pc,1):0,'practice_complete'=>$pt?round($done*100/$pt,1):0];}
public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$values=$this->auto($p->id);$indicators=DB::table('quality_indicators')->where('active',1)->orderBy('category')->get();foreach($indicators as $x){$x->value=$x->source_type==='auto'?($values[$x->code]??null):DB::table('quality_measurements')->where(['quality_indicator_id'=>$x->id,'academic_period_id'=>$p->id])->orderByDesc('measured_on')->value('value');$x->ok=$x->value!==null&&($x->direction==='lower'?$x->value<=$x->target_value:$x->value>=$x->target_value);}$stats=['audits'=>DB::table('quality_audits')->where('academic_period_id',$p->id)->count(),'open_findings'=>DB::table('quality_findings as f')->join('quality_audits as a','a.id','=','f.quality_audit_id')->where('a.academic_period_id',$p->id)->where('f.status','open')->count(),'overdue'=>DB::table('quality_actions')->whereNotIn('status',['done','cancelled'])->where('due_on','<',date('Y-m-d'))->count(),'risks'=>DB::table('quality_risks')->where(['academic_period_id'=>$p->id,'status'=>'open'])->count()];return view('quality.index',compact('p','indicators','stats'));}
public function indicators(Request $r){$this->ok($r,true);$p=$r->attributes->get('academic_period');$rows=DB::table('quality_indicators')->orderBy('category')->get();return view('quality.indicators',compact('rows','p'));}
public function indicatorStore(Request $r){$this->ok($r,true);$d=$r->validate(['code'=>'required|string|max:100|unique:quality_indicators,code','name'=>'required|string|max:500','category'=>'required|string|max:255','unit'=>'required|string|max:50','target_value'=>'nullable|numeric','direction'=>'required|in:higher,lower','description'=>'nullable|string|max:5000']);DB::table('quality_indicators')->insert($d+['source_type'=>'manual','active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function measurement(Request $r,$indicator){$this->ok($r,true);$p=$r->attributes->get('academic_period');$d=$r->validate(['value'=>'required|numeric','measured_on'=>'required|date','comment'=>'nullable|string|max:5000']);DB::table('quality_measurements')->insert($d+['quality_indicator_id'=>$indicator,'academic_period_id'=>$p->id,'scope_type'=>'college','source'=>'manual','recorded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}